    if(wasLegacyOfficial){data.officialRevision=official.revision;data.roomBoundary=clone(base.roomBoundary);data.walls=clone(base.walls);data.glassWalls=clone(base.glassWalls);data.doors=clone(base.doors);data.windows=clone(base.windows);data.structures=clone(base.structures);data.dimensions=clone(base.dimensions);data.spaces=clone(base.spaces);}
