  function fitView(){const r=wrap.getBoundingClientRect(),vs=state.roomBoundary.vertices;const minX=Math.min(...vs.map(v=>v.x)),maxX=Math.max(...vs.map(v=>v.x)),minY=Math.min(...vs.map(v=>v.y)),maxY=Math.max(...vs.map(v=>v.y));view.zoom=Math.min((r.width-150)/(maxX-minX),(r.height-100)/(maxY-minY));view.zoom=Math.max(.25,Math.min(2,view.zoom));view.panX=(r.width-(maxX-minX)*view.zoom)/2-minX*view.zoom;view.panY=(r.height-(maxY-minY)*view.zoom)/2-minY*view.zoom;updateZoom();render();}
