  function drawGrid(w,h){if(!state.settings.showGrid)return;const step=Math.max(12,state.gridSize*view.zoom);ctx.save();ctx.strokeStyle='#d7dde6';ctx.lineWidth=1;ctx.globalAlpha=.65;const ox=((view.panX%step)+step)%step,oy=((view.panY%step)+step)%step;ctx.beginPath();for(let x=ox;x<w;x+=step){ctx.moveTo(x,0);ctx.lineTo(x,h)}for(let y=oy;y<h;y+=step){ctx.moveTo(0,y);ctx.lineTo(w,y)}ctx.stroke();ctx.restore();}
  function pathRoom(){const vs=state.roomBoundary.vertices;ctx.beginPath();vs.forEach((v,i)=>i?ctx.lineTo(v.x,v.y):ctx.moveTo(v.x,v.y));ctx.closePath();}
  function drawRoom(){const invalid=selfIntersects(state.roomBoundary.vertices);pathRoom();ctx.fillStyle=invalid?'rgba(219,75,82,.06)':'rgba(255,255,255,.82)';ctx.fill();ctx.strokeStyle=invalid?palette.red:palette.wall;ctx.lineWidth=8/view.zoom;ctx.lineJoin='round';ctx.stroke();
    if(tool==='vertices'){state.roomBoundary.vertices.forEach((v,i)=>{ctx.beginPath();ctx.arc(v.x,v.y,7/view.zoom,0,Math.PI*2);ctx.fillStyle=selected?.kind==='vertex'&&selected.index===i?'#3276e8':'#fff';ctx.fill();ctx.strokeStyle='#3276e8';ctx.lineWidth=2/view.zoom;ctx.stroke();});}
    if(tool==='walls'||selected?.kind==='wall'){const vs=state.roomBoundary.vertices;vs.forEach((v,i)=>{const n=vs[(i+1)%vs.length],active=selected?.kind==='wall'&&selected.index===i;ctx.beginPath();ctx.moveTo(v.x,v.y);ctx.lineTo(n.x,n.y);ctx.strokeStyle=active?palette.blue:'rgba(50,118,232,.45)';ctx.lineWidth=(active?7:3)/view.zoom;ctx.stroke();if(state.settings.showDimensions){const m={x:(v.x+n.x)/2,y:(v.y+n.y)/2};ctx.fillStyle=palette.ink;ctx.font=`${10/view.zoom}px sans-serif`;ctx.textAlign='center';ctx.fillText(`${Math.round(distance(v,n))} cm`,m.x,m.y-9/view.zoom);}});}
    if(invalid){const p=state.roomBoundary.vertices[0];ctx.fillStyle=palette.red;ctx.font=`${12/view.zoom}px sans-serif`;ctx.fillText('외곽선이 교차합니다',p.x,p.y-18/view.zoom);}
  }
  function drawSpaces(){ctx.save();pathRoom();ctx.clip();state.spaces.forEach(s=>{const b=s.bounds;ctx.fillStyle=s.type==='undergrad'?'rgba(129,93,205,.025)':'rgba(243,169,59,.025)';ctx.fillRect(b.x,b.y,b.w,b.h);});ctx.restore();}
  function drawGlass(g){ctx.save();ctx.globalAlpha=g.opacity??.72;ctx.strokeStyle='rgba(76,201,232,.28)';ctx.lineWidth=Math.max(g.thickness,16/view.zoom);ctx.beginPath();ctx.moveTo(g.start.x,g.start.y);ctx.lineTo(g.end.x,g.end.y);ctx.stroke();ctx.strokeStyle=palette.glass;ctx.lineWidth=3/view.zoom;ctx.setLineDash([12/view.zoom,7/view.zoom]);ctx.stroke();ctx.setLineDash([]);ctx.globalAlpha=1;ctx.save();ctx.translate((g.start.x+g.end.x)/2,(g.start.y+g.end.y)/2);ctx.fillStyle=palette.muted;ctx.font=`${11/view.zoom}px sans-serif`;ctx.textAlign='center';ctx.fillText('유리 파티션',0,-10/view.zoom);ctx.restore();if(selected?.kind==='glass'&&selected.id===g.id){[g.start,g.end].forEach(p=>{ctx.beginPath();ctx.arc(p.x,p.y,7/view.zoom,0,Math.PI*2);ctx.fillStyle='#fff';ctx.fill();ctx.strokeStyle=palette.blue;ctx.lineWidth=2/view.zoom;ctx.stroke();});}ctx.restore();}
  function drawInternalWall(w){const a=w.start||w.startPoint,b=w.end||w.endPoint;ctx.save();ctx.strokeStyle=palette.wall;ctx.lineWidth=(w.thickness||12);ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();ctx.restore();}
  function drawWindow(w){const a=w.start||w.startPoint,b=w.end||w.endPoint;ctx.save();ctx.strokeStyle='#4da6d8';ctx.lineWidth=8/view.zoom;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();ctx.strokeStyle='#fff';ctx.lineWidth=2/view.zoom;ctx.stroke();ctx.restore();}
  function drawDoor(d){ctx.save();const warning=renderWarnings.some(w=>w.ids.includes(d.id)),down=(d.openingDirection||'').includes('down'),right=(d.openingDirection||'').includes('right'),sign=down?1:-1,hinge=right?d.width:0;ctx.translate(d.x,d.y);ctx.rotate((d.rotation||0)*Math.PI/180);ctx.strokeStyle=warning?palette.red:palette.green;ctx.lineWidth=3/view.zoom;ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(d.width,0);ctx.stroke();ctx.beginPath();ctx.arc(hinge,0,d.width,right?Math.PI:sign*Math.PI/2,right?Math.PI+sign*Math.PI/2:0,sign<0);ctx.strokeStyle=warning?palette.red:'rgba(46,157,116,.65)';ctx.lineWidth=2/view.zoom;ctx.stroke();ctx.beginPath();ctx.moveTo(hinge,0);ctx.lineTo(hinge,sign*d.width);ctx.stroke();if(selected?.kind==='door'&&selected.id===d.id){ctx.beginPath();ctx.arc(hinge,0,7/view.zoom,0,Math.PI*2);ctx.fillStyle=palette.blue;ctx.fill();}ctx.restore();}
  function drawStructure(o){const w=o.w||o.width,h=o.h||o.height,point=['outlet','lan'].includes(o.type),symbolOnly=point||o.type==='distribution';ctx.save();ctx.translate(o.x,o.y);ctx.rotate((o.rotation||0)*Math.PI/180);ctx.fillStyle=o.type==='column'?'#526077':o.type==='outlet'?'#2f74d0':o.type==='lan'?'#d83b45':o.type==='distribution'?'#fff4b8':'#cad3de';if(point){ctx.beginPath();ctx.arc(0,0,Math.max(5/view.zoom,4),0,Math.PI*2);ctx.fill();}else{ctx.fillRect(-w/2,-h/2,w,h);ctx.strokeStyle=o.type==='distribution'?'#d1a62d':selected?.id===o.id?palette.blue:'#7d8999';ctx.lineWidth=(selected?.id===o.id?3:1.5)/view.zoom;ctx.strokeRect(-w/2,-h/2,w,h);}if(!symbolOnly){ctx.fillStyle=o.type==='column'?'#fff':palette.ink;ctx.textAlign='left';ctx.textBaseline='middle';ctx.font=`${10/view.zoom}px sans-serif`;ctx.fillText(o.label||o.name,-w/2+4/view.zoom,0);}ctx.restore();}
  function drawFurniture(o){const warning=renderWarnings.some(w=>w.ids.includes(o.id)),isSelected=selected?.id===o.id||(selected?.kind==='multi'&&selected.ids.includes(o.id)),angle=(o.rotation||0)*Math.PI/180;ctx.save();ctx.translate(o.x,o.y);ctx.rotate(angle);ctx.fillStyle=o.color;ctx.globalAlpha=o.opacity??.88;roundRect(ctx,-o.w/2,-o.h/2,o.w,o.h,Math.min(8,o.h/4));ctx.fill();ctx.globalAlpha=1;ctx.strokeStyle=warning?palette.red:isSelected?palette.blue:'rgba(33,48,73,.42)';ctx.lineWidth=(warning||isSelected?3:1.5)/view.zoom;ctx.stroke();if(isSelected&&selected.kind!=='multi'){ctx.beginPath();ctx.arc(0,-o.h/2-18/view.zoom,6/view.zoom,0,Math.PI*2);ctx.fillStyle=palette.blue;ctx.fill();ctx.beginPath();ctx.moveTo(0,-o.h/2);ctx.lineTo(0,-o.h/2-12/view.zoom);ctx.strokeStyle=palette.blue;ctx.lineWidth=2/view.zoom;ctx.stroke();ctx.fillStyle='#fff';ctx.fillRect(o.w/2-5/view.zoom,o.h/2-5/view.zoom,10/view.zoom,10/view.zoom);ctx.strokeRect(o.w/2-5/view.zoom,o.h/2-5/view.zoom,10/view.zoom,10/view.zoom);}ctx.rotate(-angle);ctx.fillStyle='#24344f';ctx.textAlign='center';ctx.textBaseline='middle';ctx.font=`${Math.max(10,12/view.zoom)}px sans-serif`;ctx.fillText(o.name,0,0);if(o.locked){ctx.fillStyle=palette.ink;ctx.font=`${12/view.zoom}px sans-serif`;ctx.fillText('🔒',Math.min(o.w,o.h)/2-10/view.zoom,-Math.min(o.w,o.h)/2+10/view.zoom);}ctx.restore();if(altDown&&selected?.id===o.id)drawNearbyDistances(o);}
  function drawNearbyDistances(o){const peers=state.furniture.filter(x=>x.id!==o.id).sort((a,b)=>distance(o,a)-distance(o,b)).slice(0,2);peers.forEach(p=>{const d=Math.max(0,Math.round(distance(o,p)-(Math.max(o.w,o.h)+Math.max(p.w,p.h))/2));ctx.save();ctx.strokeStyle='#8c55d9';ctx.fillStyle='#663bb0';ctx.lineWidth=1/view.zoom;ctx.setLineDash([4/view.zoom,3/view.zoom]);ctx.beginPath();ctx.moveTo(o.x,o.y);ctx.lineTo(p.x,p.y);ctx.stroke();ctx.setLineDash([]);ctx.font=`${10/view.zoom}px sans-serif`;ctx.fillText(`${d} cm`,(o.x+p.x)/2,(o.y+p.y)/2-5/view.zoom);ctx.restore();});}
  function localPoint(p,o){const a=-(o.rotation||0)*Math.PI/180,dx=p.x-o.x,dy=p.y-o.y;return{x:dx*Math.cos(a)-dy*Math.sin(a),y:dx*Math.sin(a)+dy*Math.cos(a)};}
  function selectedHandle(p){if(selected?.kind!=='furniture')return null;const o=getObject(),q=localPoint(p,o),tol=12/view.zoom;if(distance(q,{x:0,y:-o.h/2-18/view.zoom})<tol)return'rotate';if(distance(q,{x:o.w/2,y:o.h/2})<tol)return'resize';return null;}
