  $('#properties').addEventListener('click',e=>{const b=e.target.closest('[data-prop]');if(!b)return;const action=b.dataset.prop,o=getObject();if(action==='delete')deleteSelected();if(action==='duplicate')duplicateSelected();if(action==='rotate'&&o?.rotation!=null){snapshot();o.rotation=(o.rotation+90)%360;commit();}if(['horizontal','vertical'].includes(action)&&['wall','glass'].includes(selected?.kind)){snapshot();if(action==='horizontal')o.end.y=o.start.y;else o.end.x=o.start.x;commit(`${action==='horizontal'?'수평':'수직'}으로 정렬했습니다.`);}if(action==='split'&&['wall','glass'].includes(selected?.kind))splitSelectedLine();if(action==='merge')mergeSelectedWall();});
  function splitSelectedLine(){const o=getObject();if(!o)return;snapshot();if(selected.kind==='wall'){const m={id:uid('v'),x:(o.start.x+o.end.x)/2,y:(o.start.y+o.end.y)/2};state.roomBoundary.vertices.splice(selected.index+1,0,m);selected={kind:'wall',index:selected.index,id:`wall-${selected.index}`};}else{const m={x:(o.start.x+o.end.x)/2,y:(o.start.y+o.end.y)/2},copy={...clone(o),id:uid('glass'),start:clone(m)};o.end=clone(m);state.glassWalls.push(copy);selected={kind:'glass',id:copy.id};}commit('선분을 두 구간으로 나눴습니다.');}
