  function polygonArea(vs){let sum=0;for(let i=0;i<vs.length;i++){const a=vs[i],b=vs[(i+1)%vs.length];sum+=a.x*b.y-b.x*a.y;}return Math.abs(sum)/2;}
  function pointInPolygon(p,vs){let inside=false;for(let i=0,j=vs.length-1;i<vs.length;j=i++){const a=vs[i],b=vs[j];if(((a.y>p.y)!==(b.y>p.y))&&(p.x<(b.x-a.x)*(p.y-a.y)/(b.y-a.y)+a.x))inside=!inside;}return inside;}
  function rectCorners(o){const a=(o.rotation||0)*Math.PI/180,c=Math.cos(a),s=Math.sin(a);return[[-o.w/2,-o.h/2],[o.w/2,-o.h/2],[o.w/2,o.h/2],[-o.w/2,o.h/2]].map(([x,y])=>({x:o.x+x*c-y*s,y:o.y+x*s+y*c}));}
