  function getWarnings(){const out=[],fs=state.furniture,vs=state.roomBoundary.vertices,minGlass=30;fs.forEach(o=>{if(rectCorners(o).some(p=>!pointInPolygon(p,vs)))out.push({text:`${o.name}이(가) 연구실 외곽선 밖으로 벗어났습니다.`,ids:[o.id]});state.doors.forEach(d=>{const zone={x:d.x+d.width/2,y:d.y-d.width/2,w:d.width,h:d.width,rotation:d.rotation||0};if(overlap(o,zone))out.push({text:`${o.name}이(가) ${d.name} 열림 영역을 침범하고 있습니다.`,ids:[o.id,d.id]});});state.glassWalls.forEach(g=>{const box=aabb(o),vertical=Math.abs(g.end.y-g.start.y)>Math.abs(g.end.x-g.start.x),radius=vertical?(box.r-box.l)/2:(box.b-box.t)/2,gap=pointSegmentDistance({x:o.x,y:o.y},g.start,g.end)-radius;if(gap<minGlass&&o.type!=='monitor')out.push({text:`${o.name}의 유리벽 안전거리가 ${Math.max(0,Math.round(gap))}cm로 기준 ${minGlass}cm보다 좁습니다.`,ids:[o.id,g.id]});});});for(let i=0;i<fs.length;i++)for(let j=i+1;j<fs.length;j++)if(overlap(fs[i],fs[j]))out.push({text:`${fs[i].name}과(와) ${fs[j].name}이(가) 서로 겹칩니다.`,ids:[fs[i].id,fs[j].id]});const fridge=fs.find(o=>o.type==='fridge');if(fridge){const access={x:fridge.x-100*Math.cos((fridge.rotation||0)*Math.PI/180),y:fridge.y-100*Math.sin((fridge.rotation||0)*Math.PI/180),w:120,h:100,rotation:fridge.rotation||0};const blocker=fs.find(o=>o.id!==fridge.id&&overlap(o,access));if(blocker)out.push({text:`${blocker.name}이(가) 냉장고 전면 접근 공간을 막고 있습니다.`,ids:[fridge.id,blocker.id]});}const monitor=fs.find(o=>o.type==='monitor');if(monitor){const front={x:monitor.x-100*Math.sin((monitor.rotation||0)*Math.PI/180),y:monitor.y+100*Math.cos((monitor.rotation||0)*Math.PI/180),w:monitor.w,h:180,rotation:monitor.rotation||0};const blocker=fs.find(o=>!['monitor','meetingTable','meetingChair'].includes(o.type)&&overlap(o,front));if(blocker)out.push({text:`${blocker.name}이(가) 대형 모니터 전면 시야를 가리고 있습니다.`,ids:[monitor.id,blocker.id]});}if(selfIntersects(vs))out.push({text:'연구실 외곽선이 자기 교차하여 저장할 수 없습니다.',ids:[]});return out;}
  function orient(a,b,c){return Math.sign((b.x-a.x)*(c.y-a.y)-(b.y-a.y)*(c.x-a.x));}
