  function meetingMetrics(){const fs=state.furniture,m=fs.find(o=>o.type==='monitor'),t=fs.find(o=>o.type==='meetingTable'),chairs=fs.filter(o=>o.type==='meetingChair'),fridge=fs.find(o=>o.type==='fridge'),doorBlocked=getWarnings().some(w=>w.ids.some(id=>state.doors.some(d=>d.id===id)));return{distance:m&&t?Math.max(0,Math.round(distance(m,t)-Math.max(m.w,t.w)/2)):null,chairs:chairs.length,access:!doorBlocked,fridge:!!fridge};}
  function minimumAisle(){if(!state.furniture.length)return null;let min=Infinity;state.furniture.forEach(o=>{const radius=Math.max(o.w,o.h)/2;boundarySegments().forEach(([a,b])=>{const gap=pointSegmentDistance(o,a,b)-radius;if(gap>=0)min=Math.min(min,gap);});});for(let i=0;i<state.furniture.length;i++)for(let j=i+1;j<state.furniture.length;j++){const a=state.furniture[i],b=state.furniture[j],gap=distance(a,b)-(Math.max(a.w,a.h)+Math.max(b.w,b.h))/2;if(gap>=0)min=Math.min(min,gap);}return Number.isFinite(min)?Math.round(min):null;}
  function updateAnalysis(){const area=polygonArea(state.roomBoundary.vertices)/10000,occupied=state.furniture.reduce((s,o)=>s+o.w*o.h,0)/10000,seats=state.furniture.reduce((s,o)=>s+(o.seats||0),0),deskCount=state.furniture.filter(o=>['desk','existingDesk'].includes(o.type)).length,chairCount=state.furniture.filter(o=>['chair','meetingChair'].includes(o.type)).length,warnings=getWarnings(),aisle=minimumAisle(),mm=meetingMetrics();$('#stat-area').textContent=`${area.toFixed(1)} m²`;$('#stat-occupied').textContent=`${occupied.toFixed(1)} m²`;$('#stat-occupancy').textContent=`${area?Math.round(occupied/area*100):0}%`;$('#stat-remaining').textContent=`${Math.max(0,area-occupied).toFixed(1)} m²`;$('#stat-desks').textContent=deskCount;$('#stat-chairs').textContent=chairCount;$('#stat-seats').textContent=seats;$('#stat-meeting-seats').textContent=mm.chairs;$('#stat-aisle').textContent=aisle==null?'—':`${aisle} cm`;$('#stat-warnings').textContent=warnings.length;$('#warning-count').textContent=warnings.length;$('#warning-list').innerHTML=warnings.length?warnings.map(w=>`<li class="warning-item">${escapeHtml(w.text)}</li>`).join(''):'<li class="all-clear"><span>✓</span>현재 배치에 문제가 없습니다.</li>';$('#meeting-analysis').innerHTML=`<div class="meeting-metric"><span>모니터–테이블 거리</span><b>${mm.distance==null?'미배치':`${mm.distance} cm`}</b></div><div class="meeting-metric"><span>회의용 좌석</span><b>${mm.chairs}석</b></div><div class="meeting-metric"><span>출입구 접근</span><b>${mm.access?'확보':'차단'}</b></div><div class="meeting-metric"><span>냉장고</span><b>${mm.fridge?'배치됨':'미배치'}</b></div>`;updatePrintReport({area,occupied,seats,deskCount,chairCount,warnings,aisle,mm});}
  function updatePrintReport(a){$('#print-meta').textContent=`${state.projectName} · ${new Date().toLocaleDateString('ko-KR')} · ${state.orientation.label} · 축척 ${$('#scale-label').textContent}`;$('#print-analysis').textContent=`전체 면적: ${a.area.toFixed(1)} m²\n가구 점유 면적: ${a.occupied.toFixed(1)} m²\n잔여 면적: ${(a.area-a.occupied).toFixed(1)} m²\n책상: ${a.deskCount}개\n의자: ${a.chairCount}개\n전체 좌석: ${a.seats}석\n회의 좌석: ${a.mm.chairs}석\n최소 통로 폭: ${a.aisle==null?'—':`${a.aisle} cm`}\n경고: ${a.warnings.length}건`;$('#print-targets').textContent='사용자 구분 없는 공통 가구 유형을 사용합니다.';$('#print-furniture').textContent=state.furniture.map(o=>`${o.name} · ${o.w}×${o.h}cm · (${Math.round(o.x)}, ${Math.round(o.y)})`).join('\n')||'가구 없음';$('#print-warnings').textContent=a.warnings.length?a.warnings.map((w,i)=>`${i+1}. ${w.text}`).join('\n'):'경고 없음';}
